import 'package:flutter/material.dart';
import 'package:hive_flutter/hive_flutter.dart';
import '../main.dart';
class DocsWidget extends StatefulWidget{const DocsWidget({super.key});@override State<DocsWidget> createState()=>_DocsWidgetState();}
class _DocsWidgetState extends State<DocsWidget>{late final Box box;late final TextEditingController ctrl;String title='Untitled';bool bold=false,italic=false,underline=false;@override void initState(){super.initState();box=Hive.box('pocketdex_notes');title=box.get('currentDoc',defaultValue:'Untitled');ctrl=TextEditingController(text:Map<String,String>.from(box.get('docs',defaultValue:<String,String>{}))[title]??'');}void save(){final m=Map<String,String>.from(box.get('docs',defaultValue:<String,String>{}));m[title]=ctrl.text;box.put('docs',m);box.put('currentDoc',title);}
@override Widget build(BuildContext context)=>Column(children:[Row(children:[Expanded(child:DropdownButton<String>(isExpanded:true,hint:Text(title),items:Map<String,String>.from(box.get('docs',defaultValue:<String,String>{})).keys.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v){if(v!=null)setState((){title=v;ctrl.text=Map<String,String>.from(box.get('docs',defaultValue:<String,String>{}))[v]??'';});})),IconButton(onPressed:()=>setState((){title='Untitled';ctrl.clear();}),icon:const Icon(Icons.add,color:gold)),IconButton(onPressed:save,icon:const Icon(Icons.save,color:gold))]),Wrap(children:[_tool('B',bold,()=>setState(()=>bold=!bold)),_tool('I',italic,()=>setState(()=>italic=!italic)),_tool('U',underline,()=>setState(()=>underline=!underline)),TextButton(onPressed:()=>ctrl.text='# ${ctrl.text}',child:const Text('H1')),TextButton(onPressed:()=>ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('PDF Exported'))),child:const Text('Export PDF'))]),Expanded(child:TextField(controller:ctrl,maxLines:null,expands:true,style:TextStyle(fontWeight:bold?FontWeight.bold:FontWeight.normal,fontStyle:italic?FontStyle.italic:FontStyle.normal,decoration:underline?TextDecoration.underline:TextDecoration.none),onChanged:(_)=>save(),decoration:const InputDecoration(hintText:'Document text',border:InputBorder.none))) ]);
Widget _tool(String label,bool active,VoidCallback cb)=>TextButton(onPressed:cb,child:Text(label,style:TextStyle(color:active?gold:Colors.white,fontWeight:label=='B'?FontWeight.bold:null,fontStyle:label=='I'?FontStyle.italic:null,decoration:label=='U'?TextDecoration.underline:null)));}
